if (typeof state.amount !== 'number') state.amount = 250;
function update(){
  ui.value('amount', String(state.amount));
  ui.text('result', String(state.amount * 12));
}
ui.on('amount','input',function(e){
  var v = Number(e.value);
  state.amount = isNaN(v) ? 0 : v;
  ui.text('result', String(state.amount * 12));
  ui.persist();
});
update();

if (typeof state.amount !== 'number') state.amount = 700;
function update(){
  ui.value('amount', String(state.amount));
  ui.text('month', String(state.amount));
  ui.text('year', String(state.amount * 12));
  ui.text('result', String(state.amount * 12));
}
ui.on('amount','input',function(e){
  var v = Number(e.value);
  state.amount = isNaN(v) ? 0 : v;
  update();
  ui.persist();
});
update();
